  requireTwoFactor: z.boolean(),
  digestHourUtc: z.number().int().min(0).max(23),
  enabledFlagOverrides: z.array(z.string()),
};

export const organizationSettingsSchema = z.object({
  defaultIssueStatus: organizationSettingsShape.defaultIssueStatus.default(
    "backlog",
  ),
  allowPublicProjects: organizationSettingsShape.allowPublicProjects.default(
    false,
  ),
  requireTwoFactor: organizationSettingsShape.requireTwoFactor.default(false),
  digestHourUtc: organizationSettingsShape.digestHourUtc.default(7),
  enabledFlagOverrides: organizationSettingsShape.enabledFlagOverrides.default(
    [],
  ),
});

// No `.default()`: unlike `organizationSettingsSchema`, this must leave
// omitted keys absent (not defaulted) so a partial settings patch only
// touches the fields the caller actually submitted.
export const organizationSettingsPatchSchema = z
  .object(organizationSettingsShape)
  .partial();

export const createOrganizationSchema = z.object({
  name: z.string().min(2).max(64),
  slug: slugSchema,
  plan: planIdSchema.default("free"),
});

export const updateOrganizationSchema = z.object({
